 public const VERSION='workspace-film-packaging-v1';
 public function brand(MarketingProject $p):array{return app(MarketingPackagingAssets::class)->brand($p);}
 public function settings(array $input):array {
  $d=Validator::make(['s'=>$input],['s'=>'required|array:enabled,template,duration,company,cta,track,volume,duck,fade,logo_sha256','s.enabled'=>'required|boolean','s.template'=>'required|in:minimal,cta,product','s.duration'=>'required|integer|min:2|max:5','s.company'=>'required|string|max:70','s.cta'=>'present|nullable|string|max:45','s.track'=>'present|nullable|string|max:64','s.volume'=>'required|integer|min:0|max:100','s.duck'=>'required|boolean','s.fade'=>'required|boolean','s.logo_sha256'=>'present|nullable|string|regex:/^[a-f0-9]{64}$/'])->validate()['s'];
  foreach(['enabled','duck','fade'] as $k)$d[$k]=(bool)$d[$k];foreach(['duration','volume'] as $k)$d[$k]=(int)$d[$k];$d['company']=trim($d['company']);$d['cta']=trim($d['cta']??'');abort_if($d['company']==='',422,'公司名称不能为空。');return $d;
 }
 public function content(MarketingVideoFilm $f):MarketingVideoFilm {
  if(($f->input['version']??'')!==self::VERSION)return $f;
  return MarketingVideoFilm::where('project_id',$f->project_id)->where('owner_id',$f->owner_id)->where('status','completed')->findOrFail($f->input['content_film_id']);
 }
 public function replacementSource(MarketingVideoFilm $f):MarketingVideoFilm {
  abort_unless($f->status==='completed',409);app(MarketingVideoFiles::class)->file($f->output_path,$f->output_sha256);
  if(($f->input['version']??'')===self::VERSION)abort_unless(hash_equals($f->fingerprint,MarketingEditingDigest::hash($f->input)),409,'原包装配方已变化。');
  $content=$this->content($f);abort_unless(($content->input['version']??'')!==self::VERSION,409);app(MarketingWorkspaceFilm::class)->assertCurrent($content);app(MarketingVideoFiles::class)->file($content->output_path,$content->output_sha256);return $content;
 }
 private function snapshot(array $a):array{unset($a['path']);return $a;}
 public function prepare(string $project,int $owner,string $request,string $baseId,string $baseHash,array $settings,?array $subtitles=null,?array $informationCards=null,?array $framing=null,?array $emphasis=null,?array $overlays=null,?array $speed=null,bool $speedProvided=false,?array $semantic=null):MarketingVideoFilm {
  if($semantic===null){$prior=MarketingVideoFilm::where('project_id',$project)->where('owner_id',$owner)->find($baseId);$semantic=$prior?->input['semantic']??null;}if($semantic!==null)abort_unless(MarketingSemanticProof::valid($semantic),409);
  $settings=$this->settings($settings);$payloadData=['film'=>$baseId,'hash'=>$baseHash,'settings'=>$settings];if($subtitles!==null)$payloadData['subtitles']=$subtitles;if($informationCards!==null)$payloadData['information_cards']=$informationCards;if($framing!==null)$payloadData['framing']=$framing;if($emphasis!==null)$payloadData['emphasis']=$emphasis;if($overlays!==null)$payloadData['overlays']=$overlays;if($speedProvided)$payloadData['speed']=$speed;if($semantic!==null)$payloadData['semantic']=$semantic;$payload=MarketingEditingDigest::hash($payloadData);
  return DB::transaction(function()use($project,$owner,$request,$baseId,$baseHash,$settings,$payload,$subtitles,$informationCards,$framing,$emphasis,$overlays,$speed,$speedProvided,$semantic){
   $p=app(MarketingClipSource::class)->project($project,$owner);MarketingProject::whereKey($project)->lockForUpdate()->firstOrFail();
   $receipt=MarketingPackagingRequest::where('project_id',$project)->where('request_id',$request)->first();if($receipt){abort_unless(hash_equals($receipt->payload_hash,$payload),409,'这个请求已用于其他设置。');return MarketingVideoFilm::where('project_id',$project)->where('owner_id',$owner)->findOrFail($receipt->film_id);}
   $base=MarketingVideoFilm::where('project_id',$project)->where('owner_id',$owner)->where('status','completed')->findOrFail($baseId);abort_unless(hash_equals($base->output_sha256??'',$baseHash),409,'基准成片已变化，请重新读取。');
   $content=$this->replacementSource($base);$assets=app(MarketingPackagingAssets::class);
   $brand=null;$product=null;if($settings['enabled']){$brand=$this->brand($p);abort_unless(hash_equals($brand['sha256'],$settings['logo_sha256']??''),409,'品牌Logo已变化，请重新审阅。');if($settings['template']==='product'){$product=$assets->product($p);abort_unless($product,422,'此项目缺少可使用的商品背景图，请先准备商品资料。');}}
   $audio=$settings['track']?$assets->audio($p,$settings['track']):null;$sourceRows=app(MarketingSubtitleService::class)->config($base);$sourceRows=$sourceRows['alignment']['scenes']??$sourceRows['scenes'];$speedPlan=app(MarketingSpeed::class)->normalize($speedProvided?$speed:($base->input['speed']??null),$sourceRows);$sourceFrames=(int)round($content->input['duration']*24);$contentFrames=app(MarketingSpeed::class)->frames($sourceRows,$speedPlan);$frames=$contentFrames+($settings['enabled']?$settings['duration']*24:0);abort_unless($frames<=2880,422,'包装后总时长不能超过120秒。');
   $input=['version'=>self::VERSION,'project_id'=>$project,'content_film_id'=>$content->id,'content_sha256'=>$content->output_sha256,'content_frames'=>$contentFrames,'source_content_frames'=>$sourceFrames,'speed'=>$speedPlan,'scenes'=>$content->input['scenes'],'cta'=>$content->input['cta'],'frames'=>$frames,'duration'=>$frames/24,'settings'=>$settings,'brand'=>$brand?$this->snapshot($brand):null,'product'=>$product?$this->snapshot($product):null,'audio'=>$audio?$this->snapshot($audio):null,'publication_authorized'=>false];if($semantic!==null)$input['semantic']=$semantic;$effective=$subtitles??($base->input['subtitles']??null);if($effective){app(MarketingSubtitleService::class)->assertPlan($base,$effective);$input['subtitles']=$effective;if($settings===($base->input['settings']??null))$input['subtitle_preserve']=['film_id'=>$base->id,'sha256'=>$baseHash];}$cards=$informationCards??($base->input['information_cards']??[]);$input['information_cards']=app(MarketingInformationCards::class)->normalize($cards,app(MarketingSubtitleService::class)->scenes($base));$effects=$framing??($base->input['framing']??[]);if($framing!==null||array_key_exists('framing',$base->input)){$input['framing']=app(MarketingFraming::class)->normalize($effects,app(MarketingSubtitleService::class)->scenes($base));$input['framing_version']=MarketingFraming::VERSION;}$highlights=$emphasis??($base->input['emphasis']??[]);if($emphasis!==null||array_key_exists('emphasis',$base->input)){$input['emphasis']=app(MarketingEmphasis::class)->normalize($highlights,app(MarketingSubtitleService::class)->scenes($base));$input['emphasis_version']=MarketingEmphasis::VERSION;}$layers=$overlays??($base->input['overlays']??[]);if($overlays!==null||array_key_exists('overlays',$base->input)){$input['overlays']=app(MarketingOverlays::class)->normalize($layers,app(MarketingSubtitleService::class)->scenes($base),$p);$input['overlay_assets']=[];foreach($input['overlays'] as $l){$img=app(MarketingOverlays::class)->image($p,$l['image_id']);if(isset($base->input['overlay_assets'][$l['image_id']]))abort_unless(hash_equals($base->input['overlay_assets'][$l['image_id']]['sha256'],$img['sha256']),409,'叠加图片已变化，请重新上传或选择其他图片。');$input['overlay_assets'][$l['image_id']]=['sha256'=>$img['sha256'],'extension'=>$img['extension']];}}if($speedPlan||$layers||array_key_exists('overlays',$base->input)||$highlights||array_key_exists('emphasis',$base->input)||$cards||array_key_exists('information_cards',$base->input)||$effects||array_key_exists('framing',$base->input)){$input['visual_recipe']=app(MarketingVisualRecipe::class)->resolve($base,$effective);if($settings===($base->input['settings']??null))$input['visual_preserve']=['film_id'=>$base->id,'sha256'=>$baseHash];unset($input['subtitle_preserve']);}if($speedPlan||($base->input['speed']??null)){unset($input['visual_preserve'],$input['subtitle_preserve']);}if(array_filter($input['emphasis']??[],fn($e)=>isset($e['grounding']))){$checked=app(MarketingSemanticGeometry::class)->audit($base,['state'=>['emphasis'=>$input['emphasis'],'framing'=>$input['framing']??[],'information_cards'=>$input['information_cards'],'overlays'=>$input['overlays']??[]],'applied'=>[],'skipped'=>[]],(string)\Illuminate\Support\Str::uuid());$input['emphasis']=$checked['state']['emphasis'];}$digest=MarketingEditingDigest::hash($input);
   $film=MarketingVideoFilm::firstOrCreate(['project_id'=>$project,'fingerprint'=>$digest],['owner_id'=>$owner,'revision_id'=>$content->revision_id,'input'=>$input,'status'=>'queued','result'=>['composition_external_api_cost'=>0,'new_generation_requests'=>0,'publication_authorized'=>false,'adopted_from_film_id'=>$baseId,'adopted_from_sha256'=>$baseHash]]);
   MarketingPackagingRequest::create(['project_id'=>$project,'request_id'=>$request,'payload_hash'=>$payload,'film_id'=>$film->id]);if($film->wasRecentlyCreated)app(MarketingToolTasks::class)->enqueue($film);return $film;
  });
 }
 public function assertCurrent(MarketingVideoFilm $f):MarketingProject {
  abort_unless(($f->input['version']??'')===self::VERSION&&hash_equals($f->fingerprint,MarketingEditingDigest::hash($f->input)),409,'包装配方已变化。');
  app(MarketingSemanticOptimization::class)->assertFilm($f);$p=app(MarketingClipSource::class)->project($f->project_id,$f->owner_id);$content=$this->content($f);abort_unless(($content->input['version']??'')!==self::VERSION&&$content->output_sha256===$f->input['content_sha256'],409,'包装原片已变化。');app(MarketingWorkspaceFilm::class)->assertCurrent($content);app(MarketingVideoFiles::class)->file($content->output_path,$content->output_sha256);
  if($plan=$f->input['subtitles']??null)app(MarketingSubtitleService::class)->assertPlan($f,$plan);if($preserve=$f->input['subtitle_preserve']??null){$original=MarketingVideoFilm::where('project_id',$f->project_id)->where('owner_id',$f->owner_id)->findOrFail($preserve['film_id']);app(MarketingVideoFiles::class)->file($original->output_path,$preserve['sha256']);}
  $assets=app(MarketingPackagingAssets::class);if($a=$f->input['audio'])abort_unless(MarketingEditingDigest::hash($this->snapshot($assets->audio($p,$a['id'])))===MarketingEditingDigest::hash($a),409,'配乐文件或授权已变化。');
  foreach(['brand','product'] as $key)if($a=$f->input[$key]){try{$fresh=$assets->publicImage($a['source']);}catch(\Throwable){abort(409,'品牌或产品图片已变化。');}abort_unless($fresh['sha256']===$a['sha256'],409,'品牌或产品图片已变化。');}
  return $p;
 }
}
